"""Local age-encrypted Compose backup. No keys are generated by this operator tool.

Only ciphertext is published. Restore authenticates into a private temporary file
before touching PostgreSQL; the file is deleted on close, including failure paths.
"""

import argparse
import contextlib
import hashlib
import json
import os
import re
import shutil
import subprocess
import tempfile
import threading
import time
from datetime import UTC, datetime
from pathlib import Path
from uuid import uuid4

import backup_postgres as base

FORMAT = "business-ai-age-v1"
MAX_BYTES = 2 * 1024**3
MAX_METADATA = 4 * 1024**2
NAME = re.compile(r"backup-[a-f0-9]{32}")
FAILURES = (
    OSError,
    ValueError,
    RuntimeError,
    KeyError,
    TypeError,
    subprocess.SubprocessError,
)


def private(path):
    path = base.private_directory(path)
    if not path.exists():
        path.mkdir(parents=True, mode=0o700)
        if os.name == "nt":
            account = (
                base.checked(["whoami"], stdout=subprocess.PIPE).stdout.decode().strip()
            )
            base.checked(
                [
                    "icacls",
                    str(path),
                    "/inheritance:r",
                    "/grant:r",
                    account + ":(OI)(CI)F",
                ],
                stdout=subprocess.PIPE,
            )
    # Packaged Windows hosts may virtualize AppData. Persist the actual existing
    # path so native Task Scheduler/Docker see the same files as this process.
    path = path.resolve(strict=True)
    if os.name != "nt":
        if path.stat().st_mode & 0o077:
            raise ValueError("Storage/staging must be private (0700)")
    else:
        script = "$u=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value; $a=Get-Acl -LiteralPath $env:BA_BACKUP_ACL_PATH; $owner=([Security.Principal.NTAccount]$a.Owner).Translate([Security.Principal.SecurityIdentifier]).Value; if($owner -notin @($u,'S-1-5-18','S-1-5-32-544','S-1-3-4')){exit 1}; foreach($r in $a.Access){if($r.AccessControlType -eq 'Allow' -and $r.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -notin @($u,'S-1-5-18','S-1-5-32-544','S-1-3-4')){exit 1}}"
        base.checked(
            [
                shutil.which("pwsh") or "powershell",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                script,
            ],
            env={
                **{k: v for k, v in os.environ.items() if k != "PSModulePath"},
                "BA_BACKUP_ACL_PATH": str(path),
            },
            stdout=subprocess.PIPE,
        )
    return path


def write_json(path, value):
    with path.open("x", encoding="utf8") as file:
        path.chmod(0o600)
        json.dump(value, file, ensure_ascii=False, indent=2)
        file.flush()
        os.fsync(file.fileno())


@contextlib.contextmanager
def lock(root):
    with (root / ".backup.lock").open("a+b") as file:
        (root / ".backup.lock").chmod(0o600)
        file.seek(0)
        file.write(b"0")
        file.flush()
        file.seek(0)
        try:
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(file.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(file, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            raise RuntimeError("backup_busy") from None
        yield


class Processes:
    def __init__(self, timeout=600):
        self.items = []
        self.expired = threading.Event()
        self.timer = threading.Timer(timeout, self.stop)
        self.timer.daemon = True

    def __enter__(self):
        self.timer.start()
        return self

    def start(self, args, **kwargs):
        if self.expired.is_set():
            raise TimeoutError("pipeline_deadline")
        process = subprocess.Popen(args, stderr=subprocess.DEVNULL, **kwargs)
        self.items.append(process)
        if self.expired.is_set():
            process.kill()
        return process

    def stop(self):
        self.expired.set()
        for process in self.items:
            if process.poll() is None:
                process.kill()

    def __exit__(self, *error):
        self.timer.cancel()
        self.stop()
        for process in self.items:
            process.wait(timeout=10)


def finish(process):
    if process.wait(timeout=600):
        raise RuntimeError("pipeline_failed")


def transfer(source, destination=None, limit=MAX_BYTES):
    digest, count = hashlib.sha256(), 0
    while chunk := source.read(1024 * 1024):
        count += len(chunk)
        if count > limit:
            raise ValueError("payload_limit")
        digest.update(chunk)
        if destination is not None:
            destination.write(chunk)
    return {"sha256": digest.hexdigest(), "bytes": count}


class Compose:
    def __init__(self, config):
        self.prefix = ["docker", "compose", "--project-directory", str(base.ROOT)]
        if config.get("project"):
            self.prefix += ["-p", config["project"]]
        for file in config.get("compose_files", [str(base.ROOT / "compose.yaml")]):
            self.prefix += ["-f", str(Path(file).resolve())]

    def db(self, *args):
        return [
            "docker",
            "exec",
            "-i",
            base.service_container("db", self.prefix),
            *args,
        ]

    def worker(self, database=None, mode="inspect"):
        options = ["-e", "PGDATABASE=" + database] if database else []
        return [
            *self.prefix,
            "run",
            "--rm",
            "--no-deps",
            "-T",
            *options,
            "api",
            "python",
            "-c",
            base.WORKER,
            mode,
        ]

    @contextlib.contextmanager
    def snapshot(self, database, processes):
        keeper = processes.start(
            self.worker(database, "hold"), stdin=subprocess.PIPE, stdout=subprocess.PIPE
        )
        line = keeper.stdout.readline(MAX_METADATA + 1)
        if len(line) > MAX_METADATA:
            raise ValueError("metadata_limit")
        source = json.loads(line)
        yield source
        keeper.stdin.write(b"done\n")
        keeper.stdin.close()
        finish(keeper)

    def dump(self, source, processes):
        return processes.start(
            self.db(
                "pg_dump",
                "-U",
                source["role"],
                "-d",
                source["database"],
                "-Fc",
                "--no-owner",
                "--no-acl",
                "--lock-wait-timeout=5s",
                "--snapshot=" + source["snapshot"],
            ),
            stdout=subprocess.PIPE,
        )

    def create(self, source, target):
        base.checked(
            self.db("createdb", "-U", source["role"], "--template=template0", target),
            stdout=subprocess.PIPE,
        )

    def restore(self, source, target, plaintext):
        base.checked(
            self.db(
                "pg_restore",
                "-U",
                source["role"],
                "-d",
                target,
                "--single-transaction",
                "--exit-on-error",
                "--no-owner",
                "--no-acl",
            ),
            stdin=plaintext,
            stdout=subprocess.PIPE,
        )

    def inspect(self, target):
        return json.loads(
            base.checked(self.worker(target), stdout=subprocess.PIPE).stdout
        )


def age_binary(config):
    binary = str(Path(config["age_binary"]).resolve(strict=True))
    version = (
        base.checked([binary, "--version"], stdout=subprocess.PIPE)
        .stdout.decode()
        .strip()
    )
    if version not in ("v1.3.2", "1.3.2"):
        raise ValueError("Expected pinned age v1.3.2")
    return binary


def encrypt(source, target, config, processes):
    recipient = config["recipient"]
    if not re.fullmatch(r"age1[0-9a-z]{58}", recipient):
        raise ValueError("Expected an X25519 age recipient")
    with target.open("xb") as file:
        target.chmod(0o600)
        process = processes.start(
            [config["age_binary"], "-r", recipient], stdin=subprocess.PIPE, stdout=file
        )
        observed = transfer(source, process.stdin)
        process.stdin.close()
        finish(process)
        file.flush()
        os.fsync(file.fileno())
    return observed


def manifest(bundle):
    if not NAME.fullmatch(bundle.name) or bundle.is_symlink():
        raise ValueError("Invalid bundle directory")
    metadata = bundle / "manifest.json"
    if metadata.is_symlink() or metadata.stat().st_size > MAX_METADATA:
        raise ValueError("Invalid manifest file")
    value = json.loads(metadata.read_text(encoding="utf8"))
    if value["format"] != FORMAT or value["id"] != bundle.name:
        raise ValueError("Unsupported bundle")
    for name in ("database.age", "metadata.age"):
        path = bundle / name
        expected = value["files"][name]
        if (
            path.is_symlink()
            or path.stat().st_size != expected["bytes"]
            or base.file_hash(path) != expected["sha256"]
        ):
            raise ValueError("ciphertext_integrity_failed")
    return value


def backup(config, backend=None):
    root = private(config["root"])
    config = {**config, "age_binary": age_binary(config)}
    database = config.get("database")
    if database is not None:
        base.restore_target(database)
    backend = backend or Compose(config)
    with lock(root):
        start = time.monotonic()
        identifier = "backup-" + uuid4().hex
        staging = private(root / (".partial-" + uuid4().hex))
        snapshot_at = datetime.now(
            UTC
        ).isoformat()  # Conservative, before exported snapshot.
        try:
            with (
                Processes() as processes,
                backend.snapshot(database, processes) as source,
            ):
                dump = backend.dump(source, processes)
                plain = encrypt(
                    dump.stdout, staging / "database.age", config, processes
                )
                finish(dump)
            metadata = {
                "format": FORMAT,
                "id": identifier,
                "snapshot_at": snapshot_at,
                "source": source,
                "plaintext": plain,
            }
            import io

            with Processes() as processes:
                encrypt(
                    io.BytesIO(json.dumps(metadata).encode()),
                    staging / "metadata.age",
                    config,
                    processes,
                )
            result = {
                "format": FORMAT,
                "id": identifier,
                "snapshot_at": snapshot_at,
                "completed_at": datetime.now(UTC).isoformat(),
                "backup_seconds": round(time.monotonic() - start, 3),
                "files": {
                    name: {
                        "sha256": base.file_hash(staging / name),
                        "bytes": (staging / name).stat().st_size,
                    }
                    for name in ("database.age", "metadata.age")
                },
            }
            write_json(staging / "manifest.json", result)
            bundle = root / identifier
            staging.rename(
                bundle
            )  # Same-filesystem atomic publication, no partial bundle visibility.
            manifest(bundle)
            return result
        finally:
            if staging.exists():
                shutil.rmtree(
                    staging
                )  # Only this invocation's private, random staging directory.


def key_path(identity, root):
    key = Path(identity).resolve(strict=True)
    if key.is_relative_to(base.ROOT) or key.is_relative_to(root):
        raise ValueError("Identity must be outside repository and backup storage")
    private(key.parent)
    if os.name != "nt" and key.stat().st_mode & 0o077:
        raise ValueError("Identity must be private (0600)")
    return str(key)


def decrypt(source, destination, binary, identity, processes, limit=MAX_BYTES):
    process = processes.start(
        [binary, "-d", "-i", identity, str(source)], stdout=subprocess.PIPE
    )
    result = transfer(process.stdout, destination, limit)
    finish(
        process
    )  # age's final authentication must succeed before any PostgreSQL action.
    return result


def recover(config, bundle, identity, target=None, backend=None):
    import io

    root = private(config["root"])
    bundle = Path(bundle).resolve(strict=True)
    public = manifest(bundle)
    binary = age_binary(config)
    identity = key_path(identity, root)
    if target is not None:
        base.restore_target(target)
    start = time.monotonic()
    staging = private(root / (".restore-" + uuid4().hex))
    try:
        with Processes() as processes:
            metadata_bytes = io.BytesIO()
            decrypt(
                bundle / "metadata.age",
                metadata_bytes,
                binary,
                identity,
                processes,
                MAX_METADATA,
            )
            metadata = json.loads(metadata_bytes.getvalue())
            if (metadata["format"], metadata["id"], metadata["snapshot_at"]) != (
                FORMAT,
                public["id"],
                public["snapshot_at"],
            ):
                raise ValueError("Authenticated manifest mismatch")
            with tempfile.TemporaryFile(dir=staging) as plaintext:
                observed = decrypt(
                    bundle / "database.age", plaintext, binary, identity, processes
                )
                if observed != metadata["plaintext"]:
                    raise ValueError("Plaintext checksum mismatch")
                authenticated_seconds = time.monotonic() - start
                if target is not None:
                    if target == metadata["source"]["database"]:
                        raise ValueError("Restoring into source is forbidden")
                    backend = backend or Compose(config)
                    backend.create(metadata["source"], target)
                    plaintext.seek(0)
                    backend.restore(metadata["source"], target, plaintext)
                    restore_seconds = time.monotonic() - start - authenticated_seconds
                    verify_start = time.monotonic()
                    restored = backend.inspect(target)
                    fields = (
                        "tables",
                        "schema_sha256",
                        "extensions",
                        "invalid_indexes",
                        "server_version",
                    )
                    if any(restored[k] != metadata["source"][k] for k in fields):
                        raise ValueError(
                            "Restored database differs; preserve target for diagnosis"
                        )
                    return {
                        "status": "PASS",
                        "id": public["id"],
                        "authentication_seconds": round(authenticated_seconds, 3),
                        "restore_seconds": round(restore_seconds, 3),
                        "verification_seconds": round(
                            time.monotonic() - verify_start, 3
                        ),
                        "total_seconds": round(time.monotonic() - start, 3),
                        "tables": restored["tables"],
                    }
                return {
                    "status": "AUTHENTICATED",
                    "id": public["id"],
                    "seconds": round(time.monotonic() - start, 3),
                }
    finally:
        shutil.rmtree(staging)


def status(root, now=None):
    root = private(root)
    now = now or datetime.now(UTC)
    journal = root / "events.jsonl"
    last_attempt = None
    if journal.exists():
        try:
            last_attempt = json.loads(
                journal.read_text(encoding="utf8").splitlines()[-1]
            )
        except (OSError, ValueError, IndexError):
            last_attempt = {"event": "journal_unreadable"}
    attempt_failed = bool(last_attempt and last_attempt["event"] != "backup_success")
    valid, invalid = [], 0
    for bundle in root.glob("backup-*"):
        try:
            value = manifest(bundle)
            timestamp = datetime.fromisoformat(value["snapshot_at"])
            age = (now - timestamp).total_seconds()
            if age < 0:
                raise ValueError("Future snapshot timestamp")
            valid.append((timestamp, value, age))
        except (OSError, ValueError, KeyError):
            invalid += 1
    if not valid:
        return {
            "status": "MISSING",
            "invalid_bundles": invalid,
            "last_attempt": last_attempt,
            "last_attempt_failed": attempt_failed,
        }
    _, value, age = max(valid, key=lambda x: x[0])
    return {
        "status": "STALE" if age > 86400 else "OK",
        "id": value["id"],
        "snapshot_at": value["snapshot_at"],
        "completed_at": value["completed_at"],
        "age_seconds": round(age, 3),
        "invalid_bundles": invalid,
        "last_attempt": last_attempt,
        "last_attempt_failed": attempt_failed,
        "verification": "pipeline completion and ciphertext SHA; age authentication requires identity",
    }


def prune(root, keep=7, apply=False):
    if keep < 1:
        raise ValueError("Must keep at least one valid copy")
    root = private(root)
    with lock(root):
        valid = []
        for bundle in root.glob("backup-*"):
            try:
                value = manifest(bundle)
                valid.append((value["snapshot_at"], bundle))
            except (OSError, ValueError, KeyError):
                continue  # Invalid/partial/pinned bundles require manual diagnosis.
        remove = [
            path
            for _, path in sorted(valid, reverse=True)[keep:]
            if not (path / "PIN").exists()
        ]
        if apply:
            for path in remove:
                shutil.rmtree(path)
        return {"dry_run": not apply, "remove": [p.name for p in remove]}


def event(root, value):
    path = root / "events.jsonl"
    if path.exists() and path.stat().st_size > 1024**2:
        path.replace(root / "events.previous.jsonl")
    with path.open("a", encoding="utf8") as file:
        path.chmod(0o600)
        file.write(json.dumps({"at": datetime.now(UTC).isoformat(), **value}) + "\n")


def scheduled(config, backend=None, now=None):
    root = private(config["root"])
    try:
        result = backup(config, backend)
        event(
            root,
            {
                "event": "backup_success",
                "id": result["id"],
                "snapshot_at": result["snapshot_at"],
            },
        )
        result = status(root, now)
        print(json.dumps(result))
        return result
    except Exception:
        event(root, {"event": "backup_failure", "code": "operation_failed"})
        raise


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "operation", choices=["backup", "verify", "restore", "status", "prune", "watch"]
    )
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--bundle", type=Path)
    parser.add_argument("--identity", type=Path)
    parser.add_argument("--target")
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--test-interval-seconds", type=float)
    parser.add_argument("--test-runs", type=int)
    args = parser.parse_args()
    try:
        config = json.loads(args.config.read_text(encoding="utf8"))
        if args.operation == "backup":
            scheduled(config)
        elif args.operation in ("verify", "restore"):
            if (
                args.bundle is None
                or args.identity is None
                or (args.operation == "restore" and args.target is None)
            ):
                raise ValueError("Bundle/identity/restore target required")
            print(json.dumps(recover(config, args.bundle, args.identity, args.target)))
        elif args.operation == "status":
            result = status(config["root"])
            print(json.dumps(result))
            if (
                result["status"] != "OK"
                or result["invalid_bundles"]
                or result["last_attempt_failed"]
            ):
                return 2
        elif args.operation == "prune":
            print(json.dumps(prune(config["root"], apply=args.apply)))
        else:
            interval = 12 * 3600
            if args.test_interval_seconds is not None:
                if not config.get("database", "").startswith(
                    "f00_restore_"
                ) or args.test_runs not in (1, 2, 3):
                    raise ValueError(
                        "Short watch is allowed only on isolated QA with 1..3 runs"
                    )
                interval = max(1, args.test_interval_seconds)
            count = 0
            while True:
                try:
                    scheduled(config)
                except FAILURES:
                    print('{"status":"BACKUP_FAILED"}', flush=True)
                    if args.test_runs is not None:
                        return 1
                count += 1
                if args.test_runs is not None and count >= args.test_runs:
                    break
                time.sleep(interval)
    except (*FAILURES, KeyboardInterrupt):
        print('{"status":"FAILED","details":"withheld"}')
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
